void handle_timer_event(struct snd_timer_instance* timeri, int event, struct timespec* tstamp, unsigned long resolution) {
    if (!timeri || !tstamp) {
        return;
    }

    if (event < 0 || event >= SND_TIMER_EVENT_MAX) {
        return;
    }

    struct snd_timer_read read_data = {0};
    read_data.event = event;
    read_data.tstamp = *tstamp;
    read_data.resolution = resolution;

    if (!timeri->queue || !timeri->queue->lock) {
        return;
    }

    if (timeri->filter && !timeri->filter(event)) {
        return;
    }

    if (!timeri->read_available()) {
        return;
    }

    if (pthread_mutex_lock(timeri->queue->lock) != 0) {
        return;
    }

    if (timeri->queue->length >= SND_TIMER_MAX_QUEUE_SIZE) {
        pthread_mutex_unlock(timeri->queue->lock);
        return;
    }

    timeri->queue->data[timeri->queue->tail] = read_data;
    timeri->queue->tail = (timeri->queue->tail + 1) % SND_TIMER_MAX_QUEUE_SIZE;
    timeri->queue->length++;

    pthread_mutex_unlock(timeri->queue->lock);

    if (timeri->signal) {
        timeri->signal();
    }

    if (timeri->wake_up) {
        timeri->wake_up();
    }
}
